5	import { Band, Pick, PlanCard, RegionCard, AddonRow, SvcIcon, StepMarks, DiskMeter, Fold } from "./OrderBits";
6	import { Flag } from "./Bits";
7	import { RegionGlobe } from "./RegionGlobe";
8	import { PlayLockup } from "./GlobeBg";
9	import { OrderProvider, useOrder, type Catalog } from "./order";
10	import { payAndDeployGame } from "@/lib/actions-gameplans";
11	import { submitHosting, submitEmail } from "@/lib/nx/submit-hosting";
12	import { purchaseDomain } from "@/lib/actions-domains";
13	import { searchDomains, type DomainResult } from "@/lib/nx/search-domains";
