27	/** The game picker's reset chip. Not a genre, so it is not in GENRE_ORDER. */
28	const ALL_GAMES = "All games";
29	
30	/** Largest player count any of this family's sellable tiers provides. */
31	function maxSlots(g: GameFamilyOption): number | null {
32	  const counts = g.tiers.map((t) => t.slots).filter((n): n is number => typeof n === "number" && n > 0);
33	  return counts.length ? Math.max(...counts) : null;
34	}
