36	/* The billing-term selector.
37	 *
38	 * ONE component, rendered on VPS, game, hosting and email alike. It used to be
39	 * written inline in the VPS plan slide only, so the other three products — every
40	 * one of which the platform prices on the SAME ladder (`PRODUCT_TERMS` in
41	 * lib/billing-terms.ts: monthly / annual / 2yr / 3yr, all through the single
42	 * `termPriceCents` formula) and every one of whose order functions already calls
43	 * `normalizeProductTerm` — could only ever be bought monthly from this wizard.
44	 * The longer-commitment discount existed and was unreachable.
45	 *
46	 * Domains are deliberately NOT given this: a domain is sold in REGISTRATION
47	 * YEARS at the registrar's own per-year price, not on the commitment-discount
48	 * ladder, and it has its own year selector.
49	 */
50	function TermChips({ terms, months, onPick }: {
51	  terms: TermOption[]; months: number; onPick: (m: number) => void;
52	}) {
53	  return (
54	    <div className="noscroll flex w-full gap-1.5 overflow-x-auto sm:w-auto">
55	      {terms.map((t) => (
56	        <button key={t.months} type="button" onClick={() => onPick(t.months)}
57	                aria-pressed={months === t.months}
58	                className={"chip h-[30px] flex-none px-3 text-[12px] " + (months === t.months ? "chip-on" : "")}>
59	          {TERM_LABEL[t.months] ?? t.label}
60	          {t.discountPercent > 0 && (
61	            <span className="ml-1.5 text-[10px] font-bold text-mint">-{t.discountPercent}%</span>
62	          )}
63	        </button>
64	      ))}
65	    </div>
66	  );
67	}
68	
69	/* The deploy wizard, on the design's real structure.
70	 *
71	 * I had this wrong first time and the difference is structural, not cosmetic:
72	 * it is a paginated DECK — one step on screen at a time, sliding horizontally —
73	 * with a fixed summary bar along the bottom. Not a stack of bands with a cart
74	 * in a side column.
75	 *
76	 * VPS is the wired path. The other four tiles are shown COMPLETE (bullets, real
77	 * "from" price) but marked, because a tile that looks pickable and silently does
78	 * nothing is worse than one that says where it stands.
79	 *
80	 * Exactly one control can charge, and it lives on the payment slide. On the live
81	 * platform an unkeyed ternary once made Continue and Deploy the same DOM node
82	 * and charged five customers four steps early — which is why Next and Deploy are
83	 * different elements on different slides, and the bottom bar's Next stops at
84	 * payment. */
85	
86	const HERO_CHIPS: [string, string][] = [
87	  ["bolt", "Instant deployment"],
88	  ["shield", "DDoS protection"],
89	  ["globe2", "Global locations"],
90	  ["lifebuoy", "24/7 support"],
91	];
92	
93	/* Friendlier term labels. `VPS_TERMS` says "Biennial"/"Triennial" and that stays
94	   the platform's word everywhere else; the wizard says what a customer would. */
95	const TERM_LABEL: Record<number, string> = { 1: "Monthly", 12: "Annual", 24: "2 years", 36: "3 years" };
96	
97	/* Who each plan is for. Copy, not data — the plan row has specs, not an
98	   audience, and "2 vCPU · 4 GB" already appears in the card's own list. */
99	const PLAN_BLURB: Record<string, string> = {
100	  starter: "A first real server",
101	  standard: "Most people land here",
102	  pro: "Production workloads",
103	  max: "Heavy, sustained load",
104	};
105	
106	const TRUST: [string, string, string][] = [
107	  ["bolt", "Live in 47 seconds", "Provisioning starts the moment you pay"],
108	  ["shieldcheck", "Secure checkout", "256-bit encryption, no card stored unless you ask"],
109	  ["lifebuoy", "24/7 support", "Answers in about four minutes, day or night"],
110	  ["refresh", "Resize anytime", "Scale up or down with no downtime"],
111	];
112	
113	/* ── the slide deck ───────────────────────────────────────────────────────
114	   Height animates to the ACTIVE slide so the page does not size itself to the
115	   tallest one. Inactive slides are `inert`: without it a keyboard user tabs
116	   straight into the controls of a step that is scrolled off-screen. */
117	/** Deck plus the alignment check, skipped until a service is chosen. */
118	function DeckWithCheck({ service, steps, i, children }: {
119	  service: string | null; steps: number; i: number; children: React.ReactNode[];
120	}) {
121	  if (service && children.length !== steps) {
122	    // eslint-disable-next-line no-console
123	    console.error(
124	      `[deploy] slide/step mismatch for "${service}": ${children.length} slides for ${steps} steps — ` +
125	      "the deck is indexed positionally, so every step after the difference shows the wrong screen."
126	    );
127	  }
128	  return <Deck i={i} steps={steps}>{children}</Deck>;
129	}
130	
131	function Deck({ i, steps, children }: { i: number; steps: number; children: React.ReactNode[] }) {
132	  const track = useRef<HTMLDivElement>(null);
133	  const [h, setH] = useState<number | undefined>(undefined);
134	
135	  /* The deck is indexed POSITIONALLY against the step list, but the two are
136	     built by separate sets of conditionals — so a product whose slides and
137	     steps disagree silently renders the wrong screen. That is exactly how
138	     hosting, email and domains ended up walking the VPS flow: the VPS plan
139	     slide was skipped for `game` only, so for the other three the deck had one
140	     slide too many and every index landed one place early.
141	     A mismatch is a bug, and in development it should be loud rather than
142	     something a customer discovers. */
143	
144	
145	  useEffect(() => {
146	    const el = track.current?.children[i] as HTMLElement | undefined;
147	    if (!el) return;
148	    const measure = () => setH(el.offsetHeight);
149	    measure();
150	    const ro = new ResizeObserver(measure);
151	    ro.observe(el);
152	    return () => ro.disconnect();
153	  }, [i, children.length]);
154	
155	  return (
156	    <div className="deck overflow-hidden transition-[height] duration-[420ms] ease-[cubic-bezier(.4,0,.2,1)]"
157	         style={{ height: h }}>
158	      <div ref={track}
159	           className="deck-track flex items-start transition-transform duration-[420ms] ease-[cubic-bezier(.4,0,.2,1)]"
160	           style={{ transform: `translateX(-${i * 100}%)` }}>
161	        {children.map((c, n) => (
162	          <div key={n} aria-hidden={n !== i} inert={n !== i} className="w-full shrink-0 px-[2px]">{c}</div>
163	        ))}
164	      </div>
165	    </div>
166	  );
167	}
168	
169	function TrustStrip() {
170	  return (
171	    <div className="card grid gap-4 p-4 sm:grid-cols-2 xl:grid-cols-4">
172	      {TRUST.map(([ic, t, s]) => (
173	        <div key={t} className="flex items-start gap-3">
174	          <Plate name={ic} size={24} />
175	          <span className="flex min-w-0 flex-col gap-0.5">
176	            <span className="text-[13px] font-bold text-white">{t}</span>
177	            <span className="text-[11.5px] leading-[1.45] text-tx-faint">{s}</span>
178	          </span>
179	        </div>
180	      ))}
181	    </div>
182	  );
183	}
184	
185	/* ── domain search ────────────────────────────────────────────────────────
186	   The only step in the wizard that reaches an external system to answer a
187	   question. Availability and price both come from the registrar; nothing here
188	   guesses either. */
189	function DomainSearch() {
190	  const { o, set } = useOrder();
191	  const [q, setQ] = useState("");
192	  const money = useMoney();
193	  const [busy, setBusy] = useState(false);
194	  const [results, setResults] = useState<DomainResult[] | null>(null);
195	  const [err, setErr] = useState<string | null>(null);
196	  const [offline, setOffline] = useState(false);
197	
198	  async function run() {
199	    if (q.trim().length < 2) return;
200	    setBusy(true); setErr(null);
201	    const res = await searchDomains(q);
202	    setBusy(false);
203	    if (!res.ok) { setResults(null); setErr(res.error); setOffline(!!res.unavailable); return; }
204	    setOffline(false); setResults(res.results);
205	  }
206	
207	  return (
208	    <div className="flex flex-col gap-3">
209	      <div className="flex gap-2">
210	        <div className="field h-[46px] flex-1">
211	          <Icon name="search" size={16} />
212	          <input value={q} onChange={(e) => setQ(e.target.value)}
213	                 onKeyDown={(e) => { if (e.key === "Enter") { e.preventDefault(); run(); } }}
214	                 spellCheck={false} autoComplete="off" placeholder="yourname.com"
215	                 className="min-w-0 flex-1 bg-transparent text-[14px] text-white outline-none placeholder:text-tx-faint" />
216	        </div>
217	        <button onClick={run} disabled={busy || q.trim().length < 2}
218	                className="btn h-[46px] flex-none px-5 text-[13.5px] disabled:opacity-45">
219	          {busy ? "Checking…" : "Search"} {!busy && <span className="arw">→</span>}
220	        </button>
221	      </div>
222	
223	      {err && (
224	        <div className={"flex items-start gap-2.5 rounded-[8px] border px-3 py-2.5 text-[12.5px] " +
225	                        (offline ? "border-[rgba(239,168,40,0.3)] bg-[rgba(239,168,40,0.08)] text-amber"
226	                                 : "border-[rgba(239,66,108,0.3)] bg-[rgba(239,66,108,0.08)] text-rose")}>
227	          <Icon name={offline ? "warntriangle" : "xcircle"} size={15} className="flex-none" />
228	          <span>{err}</span>
229	        </div>
230	      )}
231	
232	      {results && (
233	        <div className="flex flex-col gap-2">
234	          {results.map((r) => {
235	            const on = o.domainName === r.domain;
236	            return (
237	              <Pick key={r.domain} on={on}
238	                    onClick={() => {
239	                      // Only a name that is actually FOR SALE can be selected —
240	                      // a taken one is shown so the customer knows, not offered.
241	                      if (!r.available || r.priceCents === null) return;
242	                      set("domainName", r.domain);
243	                      set("domainPriceCents", r.priceCents);
244	                    }}
245	                    className={"flex items-center gap-3 p-3 " + (r.available ? "" : "opacity-55")}>
246	                <Icon name={r.available ? "checkcircle" : "xcircle"} size={17}
247	                      className={"flex-none " + (r.available ? "text-mint" : "text-tx-faint")} />
248	                <span className="flex min-w-0 flex-1 flex-col">
249	                  <span className="trunc text-[13.5px] font-bold text-white">{r.domain}</span>
250	                  <span className="trunc text-[11px] text-tx-faint">
251	                    {r.available ? (r.premium ? "Premium name" : "Available") : "Already registered"}
252	                  </span>
253	                </span>
254	                {r.available && r.priceCents !== null && (
255	                  <span className="flex flex-none flex-col items-end">
256	                    <span className="text-[13px] font-bold text-white">{money(r.priceCents)}/yr</span>
257	                    {/* Renewal stated up front — a first-year price shown alone
258	                        is how a customer is surprised twelve months later. */}
259	                    {r.renewCents !== null && r.renewCents !== r.priceCents && (
260	                      <span className="text-[10.5px] text-tx-faint">renews {money(r.renewCents)}/yr</span>
261	                    )}
262	                  </span>
263	                )}
264	              </Pick>
265	            );
266	          })}
267	        </div>
268	      )}
269	    </div>
270	  );
271	}
272	
273	/* ── the bottom bar ───────────────────────────────────────────────────────
274	   Always carries the live total. Its Next only advances the deck; it can never
275	   place an order. */
276	function BottomBar({ i, go, onNext, hint, last }: {
277	  i: number; go: (n: number) => void; onNext: () => void; hint: string | null; last: number;
278	}) {
279	  const { o, plan, price, pricing, cat, game } = useOrder();
280	  const money = useMoney();
281	  const svc = SERVICE_TILES.find((s) => s.key === o.service);
282	  const region = cat.regions.find((r) => r.key === o.region);
283	  const extras = o.addons.length + (o.diskGb ? 1 : 0);
284	  const term = cat.terms.find((t) => t.months === o.termMonths);
285	  /* A game order's basket line is the GAME, not the generic service mark: its
286	     cover art and title, subtitled with the tier the customer picked. `plan` is
287	     the VPS plan and is null on a game order, so without this the bar read
288	     "Game Servers" with no indication of which game or which size. */
289	  const gameTier = game?.tiers.find((t) => t.id === o.gamePlanId) ?? null;
290	
291	  /* What the customer has actually chosen, PER PRODUCT.
292	   *
293	   * This whole block used to be gated on `plan` alone — the VPS plan — which is
294	   * null on every other product. So a game, hosting, email or domain order sat
295	   * here reading "Nothing selected yet / Pick a service to start" while the very
296	   * same bar displayed a real total the customer was about to be charged. The
297	   * summary now names whichever thing the current product selects.
298	   *
299	   * Domains renew per REGISTRATION YEAR, not on the commitment ladder, so they
300	   * get their own renewal wording rather than a months figure. */
301	  const picked =
302	      o.service === "game"     ? (gameTier ? `${game?.name ?? "Game"} · ${gameTier.name}` : null)
303	    : o.service === "hosting"  ? cat.hosting.find((h) => h.id === o.hostingPlanId)?.name ?? null
304	    : o.service === "email"    ? cat.email.find((e) => e.id === o.emailPlanId)?.name ?? null
305	    : o.service === "domains"  ? (o.domainName || null)
306	    : plan?.name ?? null;
307	
308	  /* True while a Minecraft order has a tier but no play address yet — the one
309	     case where the total legitimately has nothing to show. */
310	  const needsPlayAddress =
311	    o.service === "game" && !!game?.needsSubdomain && o.subdomain.trim().length <= 2;
312	
313	  const renews =
314	      o.service === "domains"
315	        ? `Renews every ${o.years === 1 ? "year" : `${o.years} years`}`
316	        : `Renews ${o.termMonths === 1 ? "monthly" : `every ${o.termMonths} months`}`;
317	
318	  return (
319	    /* The right inset clears the live-chat bubble, which is `fixed bottom-4
320	       right-4 z-[60]` — without it the bubble sits on top of Next, the one
321	       control that moves the wizard forward. */
322	    <div className="fixed inset-x-0 bottom-[68px] z-30 px-3.5 sm:px-5 lg:bottom-4 lg:left-[76px] lg:pl-6 lg:pr-[92px] xl:left-[248px]">
323	      {/* A dark island: this bar is 94%-opaque dark navy by design regardless
324	          of theme, and its service-name label used the bare `text-white`
325	          utility, which the light theme now resolves to near-black ink —
326	          invisible on a bar this dark. Same class of bug as the two hero
327	          fixes above; the island re-themes every token inside at once. */}
328	      <div className="nx-dark-island mx-auto flex max-w-[1340px] items-center gap-3 rounded-[16px] border border-rim-hi
329	                      bg-[rgba(1,15,34,0.94)] px-3.5 py-3 shadow-[0_8px_30px_-12px_rgba(0,4,14,0.9)] backdrop-blur">
330	        <button onClick={() => go(i - 1)} disabled={i === 0}
331	                className="btn-ghost h-[42px] flex-none px-4 text-[13px] disabled:opacity-40">
332	          {i === 0 ? "Cancel" : "Back"}
333	        </button>
334	
335	        {svc && (
336	          <div className="hidden min-w-0 items-center gap-2.5 md:flex">
337	            {game?.art ? (
338	              <img src={game.art} alt="" aria-hidden draggable={false}
339	                   className="h-[34px] w-[52px] flex-none rounded-[6px] object-cover ring-1 ring-rim-hi" />
340	            ) : (
341	              <SvcIcon name={svc.icon} size={30} />
342	            )}
343	            <div className="flex min-w-0 flex-col leading-[1.3]">
344	              <span className="trunc text-[12.5px] font-bold text-white">{game?.name ?? svc.name}</span>
345	              <span className="trunc text-[10.8px] text-tx-faint">
346	                {[gameTier?.name ?? plan?.name,
347	                  /* Only where a region was actually chosen — see the order
348	                     summary's note. Email and domains showed "Singapore". */
349	                  o.service === "vps" || o.service === "game" ? region?.name : null,
350	                 ].filter(Boolean).join(" · ")}
351	              </span>
352	            </div>
353	            {extras > 0 && (
354	              <span className="flex-none rounded-full border border-[rgba(72,148,255,0.32)] bg-[rgba(10,40,96,0.45)]
355	                               px-2.5 py-[3px] text-[10.5px] font-bold text-[#9dbdee]">
356	                +{extras} add-on{extras > 1 ? "s" : ""}
357	              </span>
358	            )}
359	          </div>
360	        )}
361	
362	        <div className="ml-auto flex flex-none items-baseline gap-3">
363	          <span className="hidden flex-col text-right leading-[1.35] sm:flex">
364	            <span className="trunc max-w-[240px] text-[10.5px] font-bold uppercase tracking-[0.09em] text-tx-dim">
365	              {picked
366	                ? (o.service === "domains" ? picked : `${picked} · ${term?.label ?? ""}`)
367	                : "Nothing selected yet"}
368	            </span>
369	            <span className="text-[10.5px] text-tx-faint">
370	              {/* A bare "—" total with no reason reads as broken. Minecraft is
371	                  the one product that cannot be priced until its play address
372	                  exists (the name has to be claim-checked), so say so. */}
373	              {!picked ? "Pick a service to start"
374	                : needsPlayAddress ? "Add a play address for a price"
375	                : renews}
376	            </span>
377	          </span>
378	          {/* Dimmed while re-quoting rather than blanked — a total that blinks to
379	              nothing mid-change reads as "free" for a frame. */}
380	          <span className={"num bg-[linear-gradient(96deg,#3fbcd8,#8fb0e8)] bg-clip-text text-[24px] text-transparent transition-opacity " +
381	                           (pricing ? "opacity-45" : "")}>
382	            {price ? money(price.totalCents) : "—"}
383	          </span>
384	        </div>
385	
386	        {/* Why Next did nothing, said next to the button that did nothing. */}
387	        {hint && (
388	          <span className="hidden max-w-[220px] flex-none text-right text-[11px] leading-[1.35] text-rose sm:block">
389	            {hint}
390	          </span>
391	        )}
392	        {/* NOT `go(i + 1)`: the wizard decides whether the step may be left. */}
393	        <button onClick={onNext} disabled={!o.service || i >= last}
394	                className="btn h-[42px] min-w-[104px] flex-none text-[13.5px] disabled:opacity-40">
395	          Next <span className="arw" aria-hidden>→</span>
396	        </button>
397	      </div>
398	    </div>
399	  );
400	}
401	
402	/* ── payment slide — the only place an order can be placed ─────────────── */
403	function PaymentSlide({ methods, paypalClientId, active, onEdit }: {
404	  methods: { card: boolean; paypal: boolean; crypto: boolean };
405	  /* PayPal's PUBLIC client id — safe in the browser, it is what the SDK script
406	     is keyed on. Null when PayPal is not configured for this environment. */
407	  paypalClientId: string | null;
408	  /** True only while this is the step on screen. */
409	  active: boolean;
410	  onEdit: () => void;
411	}) {
412	  const { o, set, price, pricing, priceError, cat, walletApplied, cardDue, plan, game } = useOrder();
413	  const money = useMoney();
414	  const isGame = o.service === "game";
415	  const isHosting = o.service === "hosting";
416	  const isEmail = o.service === "email";
417	  const isDomains = o.service === "domains";
418	  const c = o.contact;
419	  const ready =
420	    isGame ? !!o.gamePlanId && o.serverName.trim().length > 1 && (!game?.needsSubdomain || o.subdomain.trim().length > 2)
421	    /* A hosting order needs only a PLAN. Both name fields are optional: with
422	       neither, `placeHostingOrder` issues a free `<username>.<base>` subdomain —
423	       "Empty/omitted => a free subdomain", in its own words. Requiring one here
424	       meant the server would happily take an order the button refused to send,
425	       and the customer saw a live card form above a dead button. */
426	    : isHosting ? !!o.hostingPlanId
427	    : isEmail ? !!o.emailPlanId && o.domain.trim().length > 3
428	    : isDomains ? !!o.domainName && [c.firstName, c.lastName, c.address1, c.city,
429	                                     c.postalCode, c.country, c.phone, c.email]
430	                                     .every((v) => v.trim().length > 0)
431	    : !!o.planId && !!o.osId && o.hostname.trim().length > 1;
432	
433	  /* The platform's OWN actions, one per product — called, never reimplemented.
434	     Each owns impersonation refusal, the email-verification gate, the per-user
435	     cap, a server-side re-quote before charging, and the wallet/card split.
436	     A game order must go through `payAndDeployGame`: it validates the family's
437	     variant, claims the play subdomain and sizes the VM from the tier's base
438	     plan, none of which `payAndDeploy` knows anything about. */
439	  /* One action per product. `submitHosting` / `submitEmail` are thin adapters
440	     (lib/nx/submit-hosting.ts) around functions that take positional arguments
441	     instead of FormData — they translate, they do not decide. */
442	  const action = isGame ? payAndDeployGame
443	               : isHosting ? submitHosting
444	               : isEmail ? submitEmail
445	               : isDomains ? purchaseDomain
446	               : payAndDeploy;
447	  const [state, submit, submitting] = useActionState(
448	    action as typeof payAndDeploy,
449	    {} as { error?: string; checkout?: { clientSecret: string; publishableKey: string } }
450	  );
451	  /* The card fields are up FROM THE MOMENT this step opens, not after the
452	   * button is pressed. Stripe will not render a Payment Element without a
453	   * session, so one is prepared here as soon as an amount is known.
454	   *
455	   * THE GUARD THAT MAKES THIS SAFE, and it is the whole design:
