73	/** Least-loaded enabled+online node with account headroom. */
74	async function scheduleHostingNode(): Promise<{ id: string } | null> {
75	  const nodes = await db.hostingNode.findMany({ where: { enabled: true, status: "ONLINE" } });
76	  if (!nodes.length) return null;
77	  const loads = await Promise.all(
78	    nodes.map(async (n) => ({
79	      node: n,
80	      used: await db.hostingAccount.count({ where: { hostingNodeId: n.id, status: { in: [...LIVE_STATES] } } }),
81	    })),
82	  );
83	  const withRoom = loads.filter((l) => l.used < l.node.maxAccounts).sort((a, b) => a.used - b.used);
84	  return withRoom.length ? { id: withRoom[0].node.id } : null;
85	}
