87	/** A free jailed username on the node, derived from the email + random salt. */
88	async function pickUsername(nodeId: string, emailSeed: string): Promise<string> {
89	  for (let i = 0; i < 8; i++) {
90	    const name = deriveUsername(emailSeed, randomBytes(4).toString("hex"));
91	    if (!isValidUnixUsername(name)) continue;
92	    const taken = await db.hostingAccount.findUnique({ where: { hostingNodeId_username: { hostingNodeId: nodeId, username: name } } });
93	    if (!taken) return name;
94	  }
95	  throw new Error("Could not allocate a username — try again.");
96	}
