105	export async function orderHostingAccount(
106	  planId: string,
107	  domain: string,
108	  termMonthsRaw?: number,
109	  subdomainLabelRaw?: string,
110	  extraDiskGBRaw?: number,
111	/* Returns `HostingOrderResult`, NOT the narrower `HostingResult` it used to
112	   declare. This function has always returned whatever `orderHostingAccountFor`
113	   gives it — including `{ checkout }` when a card leg is due, and `{ needCard }`
114	   — but `HostingResult` is `{ ok?, error?, accountId? }`, with no `checkout`
115	   field at all. Every optional field meant the assignment type-checked while
116	   silently erasing the card leg from the signature, so a caller could not see
117	   it even by asking. The deploy wizard's adapter hit exactly that: no client
118	   secret reached the browser, so the card fields never appeared, and the order
119	   was reported as succeeded when it had neither been placed nor paid for.
120	   This is a type correction, not a behaviour change — the runtime values are
121	   unchanged — and this is the function's only caller. */
122	): Promise<HostingOrderResult> {
123	  const user = await requireUser();
124	  await assertNotImpersonating();
125	  const unverified = await emailVerificationError(user);
126	  if (unverified) return { error: unverified };
127	  return orderHostingAccountFor(user, planId, domain, termMonthsRaw, subdomainLabelRaw, extraDiskGBRaw);
128	}
