237	    const label = String(subdomainLabelRaw ?? "").trim().toLowerCase();
238	    if (label) {
239	      if (!isValidSubdomainLabel(label)) {
240	        return { error: "Choose a subdomain of 1–32 letters, digits or hyphens (start/end with a letter or digit)." };
241	      }
242	      name = freeSubdomainFor(label);
243	      if (!isValidHostingDomain(name)) return { error: "That subdomain isn’t a valid hostname — try a different one." };
244	      if (await isHostnameClaimed(name)) {
245	        return { error: `${name} is already taken — please choose another subdomain.` };
246	      }
247	    } else {
248	      name = tempSubdomainFor(username);
249	      if (!isValidHostingDomain(name)) return { error: "Couldn’t allocate a temporary subdomain — please try again." };
