271	      // per-user/per-IP precheck (firstMonthFreeEligible) resolved above, so an
272	      // ineligible/repeat customer now skips the doomed INSERT entirely and is charged
273	      // full price cleanly. The atomic anti-double-grant guarantee is preserved: two
274	      // concurrent ELIGIBLE orders still both run the claim, one wins, the loser's tx
275	      // poisons on P2002 and fails safe (no charge, no second free month) — retry pays
276	      // full. So exactly one free month is ever granted.
277	      if (eligible) {
278	        const claim = await claimFirstMonthFree(tx, {
279	          userId: user.id,
280	          ipHash,
281	          serviceType: "HOSTING",
282	          campaign,
283	          chargedCents: promoCharge,
284	        });
285	        if (claim.claimed) {
286	          debitCents = promoCharge;
287	          promoClaimId = claim.id;
288	        }
289	      }
290	      const note = (debitCents < fullCharge ? " — First month free" : "") + (extraGB > 0 ? ` + ${extraGB} GB storage` : "");
291	      // Term shown on the ledger line: an annual account reads "Annual ($X.XX/mo)"
292	      // so the customer sees the yearly commitment AND its real per-month rate. Uses the
293	      // PLAN per-month rate (the add-on has its own $/GB/mo shown in the storage note).
294	      const effMonthly = term > 1 ? Math.round(planTermCents / term) : 0;
295	      const termLabel = term > 1 ? `${vpsTerm(term).label} ($${(effMonthly / 100).toFixed(2)}/mo)` : vpsTerm(term).label;
296	      await debitWallet(tx, user.id, debitCents);
297	      debitedCents = debitCents;
298	      await tx.walletTransaction.create({
299	        data: { userId: user.id, amountCents: -debitCents, description: `Web Hosting: ${plan.name} for ${name} — ${termLabel}${note}` },
300	      });
301	      const acct = await tx.hostingAccount.create({
302	        // Cast: the symlinked prod Prisma client's types predate `termMonths` /
303	        // `annualDiscountPct` on HostingAccount until it is regenerated at deploy
