305	        data: {
306	          userId: user.id,
307	          hostingNodeId: node.id,
308	          planId: plan.id,
309	          username,
310	          primaryDomain: name,
311	          status: "PENDING",
312	          partnerSource: partnerSource ?? null,
313	          // Quota already folds in the purchased extra disk, so the node's setquota
314	          // (applyIsolation → taskApplyPlanLimits) provisions the right size with no
315	          // add-on awareness of its own.
316	          diskQuotaMB: effectiveDiskGB(limits.diskGB, extraGB) * 1024,
317	          extraDiskGB: extraGB,
318	          maxSites: limits.maxSites,
319	          maxDatabases: limits.maxDatabases,
320	          // The term this account was SOLD on, and the annual rate frozen at sale, so
321	          // the renewal sweep bills the SAME price it was ordered at (worker/product-renewals.ts).
322	          termMonths: term,
323	          annualDiscountPct: annualPct,
324	          expiresAt: addMonths(new Date(), term),
