328	      // Atomic hostname claim in the SAME tx as the account row. A colliding
329	      // primaryDomain (another order, or someone's subdomain/addon of the same
330	      // name racing us past the advisory isHostnameClaimed check) fails here on
331	      // UNIQUE(hostname) → the whole tx (incl. the wallet debit) rolls back.
332	      await tx.hostingHostnameClaim.create({ data: { hostname: normalizeClaimHostname(name), accountId: acct.id, kind: "PRIMARY" } });
