334	    });
335	  } catch (e) {
336	    if (isUniqueViolation(e)) {
337	      return { error: "That domain is already hosted on Nxeon. If it’s yours, contact support to move it across." };
338	    }
339	    // The generic message below is intentionally opaque to the customer, but the
340	    // REAL error must be diagnosable server-side (e.g. prod schema drift: a
341	    // HostingAccount.termMonths/annualDiscountPct column or the HostingHostnameClaim
342	    // table missing because a `prisma db push` didn't apply → the INSERT throws
343	    // here). Log it before swallowing. No money-logic change — the tx already rolled
344	    // back, so the wallet was NOT charged.
345	    console.error("[hosting.order] failed", {
346	      userId: user.id,
347	      planId,
348	      domain: name,
349	      code: (e as { code?: string })?.code,
350	      err: e instanceof Error ? e.message : e,
351	    });
352	    return { error: "Couldn’t place the order. Your wallet was not charged — try again." };
353	  }
354	
355	  await db.auditLog.create({ data: { userId: user.id, action: "hosting.order", detail: `${plan.name} · ${name}` } }).catch(() => {});
356	
357	  // Fix A — the itemised invoice DOCUMENT + its emailed PDF for a hosting order.
358	  // Fires here in the CORE placement fn, so it runs exactly once for BOTH the
359	  // wallet path (orderHostingAccount) and the card path (fulfilCheckoutSession →
360	  // placeHostingOrderCore → here). Post-commit and fully best-effort: the wallet has
361	  // already been debited, so a mail/invoice failure must NEVER surface as an order
362	  // failure. This is a separate record from the wallet-credit top-up receipt a card
363	  // order gets from lib/stripe.ts. Hosting is untaxed, so the amount is the real
364	  // debited cents (0 on a granted first-month-free — a legitimate $0 record).
365	  try {
366	    const invTermLabel = vpsTerm(term).label;
367	    const invDesc = `Web Hosting: ${plan.name} for ${name} — ${invTermLabel}`;
368	    const createdInvoice = await db.invoice.create({
369	      data: invoiceCreateData({
370	        userId: user.id,
371	        description: invDesc,
372	        status: "PAID",
373	        taxCents: 0,
374	        taxRatePercent: 0,
375	        taxCountry: null,
376	        period: { start: new Date(), end: addMonths(new Date(), term) },
377	        lineItems: [{ description: invDesc, qty: 1, unitCents: debitedCents, amountCents: debitedCents }],
378	      }),
379	    });
380	    const { sendMail, emails } = await import("./mailer");
381	    const branding = await invoiceBranding();
382	    const tpl = emails.invoiceNew(
383	      {
384	        invoiceNumber: formatInvoiceNumber(createdInvoice.number, branding.numberPrefix),
385	        amount: `$${(createdInvoice.amountCents / 100).toFixed(2)}`,
386	        dueDate: new Date().toLocaleDateString("en-US", { year: "numeric", month: "short", day: "numeric" }),
387	        description: invDesc,
388	      },
389	      true, // the itemised PDF is attached (invoiceId passed below)
390	    );
391	    await sendMail({
392	      to: user.email,
393	      subject: tpl.subject,
394	      html: tpl.html,
395	      template: tpl.template,
396	      invoiceId: createdInvoice.id,
397	      userId: user.id,
398	      kind: "invoice",
399	    });
400	  } catch {
401	    /* invoice + email is best-effort — a placed order must never fail on it */
402	  }
403	
404	  revalidatePath("/dashboard/hosting");
405	  return { ok: true, accountId };
406	}
