408	// ---------- Checkout wizard (payment-method-captured order) ------------------
409	//
410	// THE MONEY FIX. `orderHostingAccount` above debits the WALLET only. First-month-
411	// free (hosting-only) makes a monthly plan $0 for month 1, so the wallet path used
412	// to provision with NOTHING on file — and month-2's renewal had nothing to charge.
413	// `placeHostingOrder` is the wizard's single entry point and closes that gap: it
414	// REFUSES to provision unless the account has a way to bill the renewal (a saved
415	// card OR a wallet balance that already covers one renewal), it is idempotent
416	// against double-submit, and it then delegates the ACTUAL charge to the audited
417	// `orderHostingAccount` above — one debit path, never a second one.
418	//
419	// displayed === charged === renewed: this action computes NO price of its own for
420	// the debit. The wallet debit + the first-month-free reserve→confirm→release
421	// atomicity all live inside `orderHostingAccount`; `renewalCents` here is only the
422	// gate threshold and is the SAME `termPriceCents(plan.priceCents, term, annualPct)`
423	// the renewal sweep charges (worker/product-renewals.ts hostingRenewalPrice).
424	
425	export type HostingOrderInput = {
426	  planId: string;
427	  /** Empty/omitted => a free `<label|username>.<base>` subdomain (see subdomainLabel). */
428	  domain?: string;
429	  /** Customer-chosen free-subdomain label (used only when `domain` is empty). */
430	  subdomainLabel?: string;
431	  /** Optional extra storage (GB) bought at deploy, on top of the plan allowance. */
432	  extraDiskGB?: number;
433	  termMonths?: number;
434	  /** Optional catalog app to auto-install after the account provisions. */
435	  appSlug?: string;
436	  /** Client-generated token that makes a resubmit a no-op (double-submit guard). */
437	  idempotencyKey: string;
438	  /**
439	   * "Apply my balance" — mirrors the VPS wizard toggle. Defaults ON (only an explicit
440	   * `false` turns it off) so every existing caller keeps applying the wallet first.
441	   * When the balance doesn't fully cover the amount due today — because the toggle is
442	   * off, or the balance is short — the remainder is charged to a card (funding the
443	   * wallet), exactly like VPS.
444	   */
445	  useWallet?: boolean;
446	};
447	
448	export type HostingOrderResult =
449	  | { ok: true; accountId: string }
450	  | { error: string }
451	  /** No renewal-capable payment method yet — the wizard must capture a card first. */
452	  | { needCard: true; renewalCents: number }
453	  /** A card leg is due: mount this embedded Stripe checkout; fulfilment places the order. */
454	  | { checkout: EmbeddedCheckout };
455	
456	/**
457	 * The full-price single renewal of a plan/term — the gate threshold, identical to
458	 * what the renewal sweep bills so "wallet covers a renewal" means exactly that.
459	 */
460	async function hostingRenewalCents(plan: { priceCents: number }, term: number, extraGB = 0): Promise<number> {
461	  const annualPct = await annualDiscountPct();
462	  const perGbCents = await extraDiskPerGbCents();
463	  return termPriceCents(plan.priceCents, term, annualPct) + extraDiskCentsAt(extraGB, perGbCents) * term;
464	}
