466	/** Place a hosting order from the checkout wizard. See the block comment above. */
467	export async function placeHostingOrder(input: HostingOrderInput): Promise<HostingOrderResult> {
468	  const user = await requireUser();
469	  // Caught so an impersonating admin sees this message inline instead of a page
470	  // crash — the bare throw used to hit the wizard's generic error screen on
471	  // every payment attempt.
472	  try {
473	    await assertNotImpersonating();
474	  } catch (e) {
475	    return { error: e instanceof Error ? e.message : "This action is disabled while impersonating a customer." };
476	  }
477	  const unverified = await emailVerificationError(user);
478	  if (unverified) return { error: unverified };
479	
480	  // Tag the order if the customer arrived via a partner deep link (?ref=kodely on
481	  // /dashboard/deploy?product=hosting, captured into a cookie by
482	  // PartnerSourceCapture). Threaded into BOTH the wallet leg (below) and the card
483	  // leg (via the Stripe-metadata-round-tripped intent).
484	  const partnerSource = partnerSourceFromCookie(await cookies());
485	
486	  const key = String(input.idempotencyKey ?? "").trim();
487	  if (!/^[A-Za-z0-9_-]{8,64}$/.test(key)) return { error: "Couldn’t place the order — please reload and try again." };
488	
489	  const term = normalizeProductTerm(input.termMonths);
490	  const plan = await db.hostingPlan.findUnique({ where: { id: input.planId } });
491	  if (!plan || !plan.active) return { error: "That hosting plan isn’t available." };
492	
493	  const extraGB = normalizeExtraDiskAddGB(input.extraDiskGB);
494	  const renewalCents = await hostingRenewalCents(plan, term, extraGB);
495	
496	  // WALLET/CARD SPLIT — the money-path fork mirroring VPS `payAndDeploy`. The amount
497	  // due TODAY (after any first-month-free credit) is split against the balance and the
498	  // "apply my balance" toggle; `useWallet` defaults ON so the existing behaviour is
499	  // unchanged. This computes the SAME anticipated dueToday `orderHostingAccountFor`
500	  // charges (shared `hostingChargeCents`), so the card leg is a real part of the same
501	  // total, never a second price.
502	  const promoEnabled = firstMonthFreeAppliesTo("HOSTING") && (await firstMonthFreeEnabled());
503	  const ipHash = hashIp(clientIp(await headers()), process.env.AUTH_SECRET ?? "nxeon") || null;
504	  const { fullCharge, promoCharge } = await hostingChargeCents(plan, term, extraGB);
505	  const eligible = promoEnabled && (await firstMonthFreeEligible(user.id, ipHash));
506	  const dueTodayCents = eligible ? promoCharge : fullCharge;
507	  const useWallet = input.useWallet !== false;
508	  const { cardCents } = walletSplit({ dueCents: dueTodayCents, balanceCents: user.balanceCents, useWallet });
509	
510	  if (cardCents > 0) {
511	    // A card leg is due (the toggle is off, or the balance is short). Fund it by card
512	    // — the card is saved via `setup_future_usage`, which is ALSO the renewal method
513	    // the gate below requires, so there is no `needCard` on this path. On payment,
514	    // `fulfilCheckoutSession` credits the card amount to the wallet and calls
515	    // `placeHostingOrderCore` with these SAME inputs (and the same `hostorder:<key>`
516	    // idempotency), which debits the real charge — one debit path, unchanged.
517	    const checkout = await createHostingOrderPaymentSession(user, cardCents, {
518	      planId: input.planId,
519	      domain: input.domain,
520	      subdomainLabel: input.subdomainLabel,
521	      extraDiskGB: extraGB || undefined,
522	      termMonths: term,
523	      appSlug: input.appSlug,
524	      idempotencyKey: key,
525	      partnerSource,
526	    });
527	    if (!checkout) return { error: "Card payments aren’t set up yet — top up your wallet to deploy." };
528	    return { checkout };
529	  }
530	
531	  // cardCents <= 0 → the wallet covers the amount due today (or it is $0). EXISTING
532	  // wallet path, byte-for-byte — including the RENEWAL-METHOD GATE: never provision a
533	  // paid product with no way to bill the renewal. A saved card OR a wallet already
534	  // holding one renewal's worth qualifies; otherwise the wizard captures a card (which
535	  // also handles the $0-today first-month-free case).
536	  if (!hasChargeableCard(user) && user.balanceCents < renewalCents) {
537	    return { needCard: true, renewalCents };
538	  }
539	  return placeHostingOrderCore(user, input, key, term, plan, extraGB, renewalCents, partnerSource);
540	}
