542	/**
543	 * The idempotent placement + post-order bookkeeping, WITHOUT the auth/pricing/split
544	 * preamble — takes the loaded `user` explicitly so BOTH the interactive action
545	 * (`placeHostingOrder`, wallet path) and the card-funded fulfilment path
546	 * (`fulfilCheckoutSession`) drive the SAME `hostorder:<key>` idempotency claim and the
547	 * SAME audited `orderHostingAccountFor` debit. On the card path the wallet was already
548	 * topped up by `creditCheckoutSession` before this runs.
549	 */
550	async function placeHostingOrderCore(
551	  user: User,
552	  input: HostingOrderInput,
553	  key: string,
554	  term: number,
555	  plan: { maxDatabases: number },
556	  extraGB: number,
557	  renewalCents: number,
558	  partnerSource?: string,
559	): Promise<HostingOrderResult> {
560	  // IDEMPOTENCY — reuse the audited FulfilledSession one-winner primitive (its
561	  // UNIQUE(stripeSessionId) is what the card path leans on) rather than inventing a
562	  // token table. A rapid resubmit or a network retry with the same key can't create
563	  // a second account or take a second debit.
564	  const sessionKey = `hostorder:${key}`;
565	  try {
566	    await db.fulfilledSession.create({ data: { stripeSessionId: sessionKey, kind: "hostorder" } });
567	  } catch (e) {
568	    if (isUniqueViolation(e)) {
569	      const prior = await db.fulfilledSession.findUnique({ where: { stripeSessionId: sessionKey } });
570	      // A completed prior attempt: replay its result (no second charge).
571	      if (prior?.status === "DONE" && prior.detail) return { ok: true, accountId: prior.detail };
572	      // A failed prior attempt: clear it so an explicit retry can proceed.
573	      if (prior?.status === "FAILED") {
574	        await db.fulfilledSession.delete({ where: { stripeSessionId: sessionKey } }).catch(() => {});
575	      } else {
576	        // Still in flight (CLAIMED): a concurrent submit is placing it right now.
577	        return { error: "That order is already being placed — check your hosting accounts in a moment." };
578	      }
579	      // Retry after clearing a FAILED marker: re-claim, or bail if we lost the race.
580	      try {
581	        await db.fulfilledSession.create({ data: { stripeSessionId: sessionKey, kind: "hostorder" } });
582	      } catch {
583	        return { error: "That order is already being placed — check your hosting accounts in a moment." };
584	      }
585	    } else {
586	      throw e;
587	    }
588	  }
589	
590	  // Delegate the ACTUAL charge to the audited wallet path. An empty domain routes to
591	  // the free temporary subdomain. All money movement, the first-month-free atomic
592	  // claim and the hostname claim happen inside orderHostingAccountFor's transaction.
593	  const res = await orderHostingAccountFor(user, input.planId, input.domain ?? "", term, input.subdomainLabel, extraGB, partnerSource);
594	  /* Only two outcomes are legitimate HERE. This runs AFTER the card cleared, so
595	     a `checkout` (another card leg) or `needCard` would mean the customer has
596	     paid and no account was opened — an anomaly worth recording as FAILED under
597	     its own wording rather than letting an unhandled branch fall through as
598	     success. `HostingOrderResult` is a union, so each branch has to be read
599	     explicitly; the old `HostingResult` had every field optional, which is what
600	     let `{ checkout }` pass silently as "no error, no accountId". */
601	  const failed = async (why: string) => {
602	    await db.fulfilledSession
603	      .update({ where: { stripeSessionId: sessionKey }, data: { status: "FAILED", detail: why.slice(0, 500) } })
604	      .catch(() => {});
605	    return { error: why };
606	  };
607	  /* Narrowed one branch at a time so `res` itself is refined — after these
608	     three, it is the `{ ok: true; accountId: string }` member and `accountId`
609	     is known present. */
610	  if ("error" in res) return failed(res.error);
611	  if ("checkout" in res) return failed("The order still wanted a card payment after one had already cleared.");
612	  if ("needCard" in res) return failed("The order asked for a card to be added after one had already cleared.");
613	  if (!res.accountId) return failed("order failed");
614	  await db.fulfilledSession
615	    .update({ where: { stripeSessionId: sessionKey }, data: { status: "DONE", detail: res.accountId } })
616	    .catch(() => {});
617	
618	  // Deploy-funnel COMPLETION — hosting's authoritative, server-side bottom of the
619	  // funnel, the counterpart to placeOrder / placeGameOrder. Hosting does NOT flow
620	  // through the shared Stripe fulfilment bus (lib/fulfil-checkout.ts has no hosting
621	  // kind — a $0 first month captures a card in `mode:"setup"`, and the charge is the
622	  // wallet debit inside orderHostingAccount), so THIS is its shared success path.
623	  // Recorded here (not on the idempotent-replay early return above) so a retry never
624	  // double-counts. Replaces the client-side trackDeployComplete removed from
625	  // HostingDeployWizard, keeping all three products on one authoritative userId-keyed
626	  // completion. Best-effort + double-guarded so it can never disturb the placed order.
627	  try {
628	    await recordDeployFunnelComplete({ product: "hosting", step: "Complete", stepIndex: 7, userId: user.id });
629	  } catch {
630	    /* never let funnel bookkeeping affect a completed order */
631	  }
632	
633	  // Server-side Meta CAPI `Subscribe` — the free-month hosting signup is a browser-
634	  // ONLY conversion otherwise (HostingDeployWizard fires nxTrack('hosting') client-
635	  // side), so an ad blocker / privacy browser silently drops it and the campaign
636	  // never learns the signup happened. Firing it here too — with the SAME event_id
637	  // the browser pixel uses (idempotencyKey) — means Meta dedupes the two into ONE
638	  // conversion when the pixel DOES load, and still counts it when the pixel is
639	  // blocked. Value = the go-forward renewal (what optimisation should chase), NOT $0.
640	  // Best-effort: sendMetaConversion never throws, and this runs after the order is
641	  // already committed, so tracking can never affect the charge.
642	  try {
643	    const [h, ck] = await Promise.all([headers(), cookies()]);
644	    await sendMetaConversion({
645	      eventName: "Subscribe",
646	      eventId: key,
647	      email: user.email,
648	      externalId: user.id,
649	      value: renewalCents / 100,
650	      currency: "USD",
651	      clientIp: clientIp(h),
652	      userAgent: h.get("user-agent") ?? undefined,
653	      // The Meta click/browser cookies are the strongest match signals for an
654	      // ad-driven signup (an ad click sets _fbc). Passing them lifts Event Match
655	      // Quality well above the email/IP-only baseline. Absent for organic visits.
656	      fbc: ck.get("_fbc")?.value || undefined,
657	      fbp: ck.get("_fbp")?.value || undefined,
658	      sourceUrl: process.env.APP_URL ? `${process.env.APP_URL}/dashboard/deploy` : undefined,
659	    });
660	  } catch {
661	    /* tracking is best-effort — the order is already placed and charged */
