692	export async function placeHostingCardOrder(
693	  sessionId: string,
694	): Promise<HostingOrderResult | { skip: true }> {
695	  const purpose = await getCheckoutPurpose(sessionId);
696	  if (purpose.kind !== "hostOrder") return { skip: true };
697	  const user = await db.user.findUnique({ where: { id: purpose.userId } });
698	  if (!user) return { error: "user not found for paid hosting order" };
699	  const intent = purpose.intent;
700	  const term = normalizeProductTerm(intent.termMonths);
701	  const plan = await db.hostingPlan.findUnique({ where: { id: intent.planId } });
702	  if (!plan || !plan.active) return { error: "That hosting plan isn’t available." };
703	  const extraGB = normalizeExtraDiskAddGB(intent.extraDiskGB);
704	  const renewalCents = await hostingRenewalCents(plan, term, extraGB);
705	  const input: HostingOrderInput = {
706	    planId: intent.planId,
707	    domain: intent.domain,
708	    subdomainLabel: intent.subdomainLabel,
709	    extraDiskGB: intent.extraDiskGB,
710	    termMonths: intent.termMonths,
711	    appSlug: intent.appSlug,
712	    idempotencyKey: intent.idempotencyKey,
713	    useWallet: true,
714	  };
715	  return placeHostingOrderCore(user, input, intent.idempotencyKey, term, plan, extraGB, renewalCents, intent.partnerSource);
