743	/**
744	 * Queue an APP_INSTALL for a freshly-ordered (PENDING) account. Mirrors installApp
745	 * but without the ACTIVE gate — the task waits in the queue and the worker runs it
746	 * after provisioning. Generates DB credentials up front for apps that need one.
747	 */
748	async function queueHostingAppInstall(accountId: string, slug: string, maxDatabases: number, email: string): Promise<void> {
749	  // WordPress is NOT an APP_RECIPES download — it installs via its own fully-
750	  // automated WORDPRESS_INSTALL task (WP-CLI). Route the wizard's one-click
751	  // WordPress here so it queues the right task with the same credential payload
752	  // installWordPress builds (mirrors that path). Any other slug must be a known
753	  // recipe app; an unknown slug is dropped (best-effort — never voids the order).
754	  if (slug === "wordpress") {
755	    if (maxDatabases < 1) return; // WordPress needs a database — no budget, skip rather than fail
756	    const acct = await db.hostingAccount.findUnique({ where: { id: accountId }, select: { username: true } });
757	    if (!acct) return;
758	    const dbName = `${acct.username}_wp`.slice(0, 64);
759	    const dbUser = dbName.slice(0, 32);
760	    const dbPass = randomBytes(12).toString("base64url").replace(/[^A-Za-z0-9]/g, "").slice(0, 20);
761	    const adminPass = randomBytes(12).toString("base64url").replace(/[^A-Za-z0-9]/g, "").slice(0, 18);
762	    await db.hostingTask.create({
763	      data: {
764	        accountId,
765	        kind: "WORDPRESS_INSTALL",
766	        payload: JSON.stringify({ dbName, dbUser, dbPassEnc: encryptSecret(dbPass), adminUser: "admin", adminPassEnc: encryptSecret(adminPass), adminEmail: email }),
767	      },
768	    });
769	    return;
770	  }
771	  const app = hostingAppCatalog().find((x) => x.slug === slug);
772	  if (!app) return;
773	  let payload: Record<string, unknown> = { slug };
774	  if (app.needsDb) {
775	    if (maxDatabases < 1) return; // the plan has no DB budget — skip rather than fail
776	    const acct = await db.hostingAccount.findUnique({ where: { id: accountId }, select: { username: true } });
777	    if (!acct) return;
778	    const dbName = `${acct.username}_${slug}`.slice(0, 64);
779	    const dbUser = dbName.slice(0, 32);
780	    const dbPass = randomBytes(12).toString("base64url").replace(/[^A-Za-z0-9]/g, "").slice(0, 20);
781	    payload = { slug, dbName, dbUser, dbPassEnc: encryptSecret(dbPass) };
782	  }
783	  await db.hostingTask.create({ data: { accountId, kind: "APP_INSTALL", payload: JSON.stringify(payload) } });
784	}
