112	  if (!mailcowConfigured()) return "PROVISIONING";
113	
114	  const [localPart] = mailbox.address.split("@");
115	  const domain = mailbox.subscription.domainName;
116	  const quotaMB = mailbox.quotaMB ?? 1024;
117	
118	  try {
119	    // Ensure the mail domain exists before adding the mailbox.
120	    if (!(await mcDomainExists(domain))) {
121	      // A concurrent create or pre-existing domain can still error here; ignore
122	      // and let the mailbox add be the real signal.
123	      await mcCreateDomain(domain).catch(() => {});
124	    }
125	
126	    const password = randomBytes(18).toString("base64url");
127	    await mcCreateMailbox({
128	      localPart,
129	      domain,
130	      name: mailbox.address,
131	      password,
132	      quotaMB,
133	    });
134	
135	    await db.mailbox.update({
136	      where: { id: mailbox.id },
137	      data: { status: "ACTIVE", passwordEnc: encryptSecret(password) },
138	    });
139	    return "ACTIVE";
140	  } catch (e) {
141	    await db.mailbox
142	      .update({ where: { id: mailbox.id }, data: { status: "FAILED" } })
143	      .catch(() => {});
144	    console.warn(`[mailcow] provisioning ${mailbox.address} failed:`, e);
145	    return "FAILED";
146	  }
147	}
