247	/**
248	 * Subscribe one of the caller's registered domains to an email plan. Validates
249	 * domain ownership + plan availability, then atomically debits the wallet and
250	 * creates the EmailSubscription with an expiry set from the plan term.
251	 *
252	 * The subscription is created ACTIVE (billing-wise), but no mailboxes are
253	 * provisioned with a mail provider yet — that integration is pending, and the
254	 * UI surfaces every mailbox as "provisioning" until it lands.
255	 */
256	export async function orderEmailHosting(
257	  domainName: string,
258	  emailPlanId: string,
259	  termMonthsRaw?: number,
260	  /**
261	   * "Apply my balance" — mirrors the VPS/hosting wizard toggle. Defaults ON (only an
262	   * explicit `false` turns it off) so existing callers keep applying the wallet first.
263	   * When the balance doesn't fully cover the term charge — the toggle is off, or the
264	   * balance is short — the remainder is charged to a card that funds the wallet, then
265	   * the wallet path (`orderEmailHostingCore`) places the subscription.
266	   */
267	  useWallet: boolean = true,
268	): Promise<Result | { checkout: EmbeddedCheckout }> {
269	  const user = await requireUser();
270	  // Spend path: block while an admin is impersonating, so support cannot buy a
271	  // subscription with a customer's wallet while acting as them. Caught so an
272	  // impersonating admin sees this message inline instead of a page crash — the
273	  // bare throw used to hit the wizard's generic error screen on every attempt.
274	  try {
275	    await assertNotImpersonating();
276	  } catch (e) {
277	    return { error: e instanceof Error ? e.message : "This action is disabled while impersonating a customer." };
278	  }
279	  // Purchase gate: an unverified address means we cannot reach the person we
280	  // are about to charge. See lib/email-verification.ts.
281	  const unverified = await emailVerificationError(user);
282	  if (unverified) return { error: unverified };
283	
284	  const name = String(domainName ?? "")
285	    .trim()
286	    .toLowerCase()
287	    .replace(/\.$/, "");
288	  if (!name) return { error: "Enter a domain." };
289	  if (!domainRe.test(name)) return { error: "Enter a valid domain (e.g. example.com)." };
290	
291	  // Price the term for the wallet/card split. Business Email has no first-month-free,
292	  // so the amount due today IS the full term charge. Shared `emailChargeCents` with the
293	  // core below so the split and the debit can never use different formulas.
294	  const planForSplit = await db.emailPlan.findUnique({ where: { id: emailPlanId } });
295	  if (!planForSplit || !planForSplit.active) return { error: "That email plan isn't available." };
296	  const term = normalizeProductTerm(termMonthsRaw);
297	  const { fullCharge } = await emailChargeCents(planForSplit, term);
298	  const { cardCents } = walletSplit({ dueCents: fullCharge, balanceCents: user.balanceCents, useWallet });
299	
300	  if (cardCents > 0) {
301	    // A card leg is due (the toggle is off, or the balance is short). Reject an already-
302	    // taken domain BEFORE opening a paid checkout (the core re-checks authoritatively at
303	    // fulfilment), then fund the remainder by card. On payment `fulfilCheckoutSession`
304	    // credits the card amount to the wallet and calls `orderEmailHostingCore`, which
305	    // debits the real charge — one debit path.
306	    const dupe = await db.emailSubscription.findFirst({ where: { domainName: name, status: { not: "CANCELLED" } } });
307	    if (dupe) {
308	      return {
309	        error:
310	          dupe.userId === user.id
311	            ? "This domain already has an email subscription."
312	            : "That domain is already set up for email on Nxeon. If it belongs to you, contact support and we'll verify ownership and move it across.",
313	      };
314	    }
315	    const checkout = await createEmailOrderPaymentSession(user, cardCents, { domainName: name, emailPlanId, termMonths: term });
316	    if (!checkout) return { error: "Card payments aren't set up yet — top up your wallet first." };
317	    return { checkout };
318	  }
319	
320	  // cardCents <= 0 → the wallet covers the term charge. EXISTING wallet path, unchanged.
321	  return orderEmailHostingCore(user, name, emailPlanId, termMonthsRaw);
322	}
