324	/**
325	 * The wallet-charging placement core, WITHOUT the auth/split preamble — takes the
326	 * already-loaded `user` explicitly so it runs from BOTH the interactive action
327	 * (`orderEmailHosting`, wallet path) and the card-funded fulfilment path
328	 * (`placeEmailCardOrder` → `fulfilCheckoutSession`). Everything below — the domain
329	 * dupe guard, pricing, the wallet debit and the subscription create — is byte-for-byte
330	 * the wallet-only logic that used to live inline in `orderEmailHosting`.
331	 */
332	async function orderEmailHostingCore(
333	  user: User,
334	  domainName: string,
335	  emailPlanId: string,
336	  termMonthsRaw?: number,
337	): Promise<Result> {
338	  const name = String(domainName ?? "")
339	    .trim()
340	    .toLowerCase()
341	    .replace(/\.$/, "");
342	  if (!name) return { error: "Enter a domain." };
343	  if (!domainRe.test(name)) return { error: "Enter a valid domain (e.g. example.com)." };
344	
345	  // Is the domain registered inside Nxeon? If so we control its DNS and can
346	  // treat mail as pre-verifiable; otherwise it's an EXTERNAL domain that must be
347	  // verified via DNS before mail flows.
348	  const inAccount = await db.domain.findFirst({ where: { name, userId: user.id } });
349	  const external = !inAccount;
350	
351	  const plan = await db.emailPlan.findUnique({ where: { id: emailPlanId } });
352	  if (!plan || !plan.active) return { error: "That email plan isn't available." };
353	
354	  // One subscription per domain — ACROSS ALL ACCOUNTS, not just this one.
355	  //
356	  // SECURITY (fixed 2026-07-25): this lookup was scoped to `userId: user.id`,
357	  // which let anyone buy a subscription for a domain another customer already
358	  // held. That was a cross-tenant email takeover: `addMailbox` only checks that
359	  // the SUBSCRIPTION belongs to the caller, and Mailcow keys mailboxes by
360	  // ADDRESS — so an attacker could create admin@victim.com under their own
361	  // subscription, call resetMailboxPassword() (which passes its ownership check
362	  // because the row is theirs), and have the password of the victim's real, live
363	  // mailbox handed back to them. Cost of the attack: the cheapest email plan.
364	  const dupe = await db.emailSubscription.findFirst({
365	    where: { domainName: name, status: { not: "CANCELLED" } },
366	  });
367	  if (dupe) {
368	    return {
369	      error:
370	        dupe.userId === user.id
371	          ? "This domain already has an email subscription."
372	          : "That domain is already set up for email on Nxeon. If it belongs to you, contact support and we'll verify ownership and move it across.",
373	    };
374	  }
375	
376	  // Seasonal promo = HONEST intro discount on the FIRST term only. The renewal
377	  // path (worker/product-renewals.ts) bills plan.priceCents unchanged, so the
378	  // strikethrough shown on the pricing page is the real renewal price and this
379	  // discounted value is the real first-term price — displayed === charged.
380	  // Managed first-month-free. `promoCharge` mirrors the pre-existing behaviour
381	  // (the first term is free); `fullCharge` is the plan price. The credit is granted
382	  // ONLY if the atomic claim inside the charge tx succeeds — otherwise (already
383	  // redeemed by this account/IP, or the promo is off) the subscription is created
384	  // at FULL price. The eligibility pre-check only picks the balance gate so a
385	  // first-time, $0-balance customer can still subscribe free.
386	  // First-month-free is scoped to Shared Web Hosting only — Business Email always
387	  // bills full. firstMonthFreeAppliesTo("EMAIL") is false, so promoEnabled is false.
388	  const promoEnabled = firstMonthFreeAppliesTo("EMAIL") && (await firstMonthFreeEnabled());
389	  const campaign = promoCampaignFromCookie(await cookies());
390	  const ipHash = hashIp(clientIp(await headers()), process.env.AUTH_SECRET ?? "nxeon") || null;
391	  // Billing term (Monthly / Annual). The annual rate is resolved ONCE, frozen onto
392	  // the subscription, charged up front and read back at renewal — displayed ===
393	  // charged === renewed. `emailMonthlyBaseCents` is the plan's monthly base (every
394	  // seeded plan is monthly, so it is just `priceCents`).
395	  const term = normalizeProductTerm(termMonthsRaw);
396	  const { annualPct, fullCharge } = await emailChargeCents(plan, term);
397	  // Business Email is NOT a first-month-free product (firstMonthFreeAppliesTo("EMAIL")
398	  // is false), so this stays the full term charge — kept for parity with the other flows.
399	  const promoCharge = 0;
400	  const eligible = promoEnabled && (await firstMonthFreeEligible(user.id, ipHash));
401	  const anticipated = eligible ? promoCharge : fullCharge;
402	  if (user.balanceCents < anticipated) {
403	    return { error: "Insufficient balance. Top up your wallet first." };
404	  }
405	
406	  // Captured out of the charge tx for the post-commit invoice document (Fix A).
407	  let debitedCents = 0;
408	  try {
409	    await db.$transaction(async (tx) => {
410	      // Atomic claim inside the charge tx (mirrors lib/order.ts claimOrderCoupon).
411	      let debitCents = fullCharge;
412	      let promoClaimId: string | null = null;
413	      if (promoEnabled) {
414	        const claim = await claimFirstMonthFree(tx, {
415	          userId: user.id,
416	          ipHash,
417	          serviceType: "EMAIL",
418	          campaign,
419	          chargedCents: promoCharge,
420	        });
421	        if (claim.claimed) {
422	          debitCents = promoCharge;
423	          promoClaimId = claim.id;
424	        }
425	      }
426	      const note = debitCents < fullCharge ? " — First month free" : "";
427	      const effMonthly = term > 1 ? Math.round(fullCharge / term) : 0;
428	      const termLabel = term > 1 ? `${vpsTerm(term).label} ($${(effMonthly / 100).toFixed(2)}/mo)` : vpsTerm(term).label;
429	      await debitWallet(tx, user.id, debitCents);
430	      debitedCents = debitCents;
431	      await tx.walletTransaction.create({
432	        data: {
433	          userId: user.id,
434	          amountCents: -debitCents,
435	          description: `Business Email: ${plan.name} for ${name} — ${termLabel}${note}`,
436	        },
437	      });
438	      const sub = await tx.emailSubscription.create({
439	        // Cast: the symlinked prod Prisma client's types predate `termMonths` /
440	        // `annualDiscountPct` on EmailSubscription until regenerated at deploy.
441	        data: {
442	          userId: user.id,
443	          domainName: name,
444	          emailPlanId: plan.id,
445	          status: "ACTIVE",
446	          autoRenew: true,
447	          // The term the customer chose, and the annual rate frozen at sale, so the
448	          // renewal sweep bills the SAME price it was ordered at.
449	          termMonths: term,
450	          annualDiscountPct: annualPct,
451	          expiresAt: addMonths(new Date(), term),
452	          // In-account domains: we control DNS, so treat as verified now. External
453	          // domains: not verified until the customer publishes DNS + we confirm it.
454	          external,
455	          verified: !external,
456	          verifiedAt: external ? null : new Date(),
457	          verifyToken: external ? randomBytes(24).toString("hex") : null,
458	        } as Prisma.EmailSubscriptionUncheckedCreateInput,
459	      });
460	      if (promoClaimId) await setPromoOrderRef(tx, promoClaimId, sub.id, debitCents);
461	    });
462	  } catch (e) {
463	    if (e instanceof InsufficientBalanceError) {
464	      return { error: "Insufficient balance. Top up your wallet first." };
465	    }
466	    throw e;
467	  }
468	
469	  await db.auditLog.create({
470	    data: {
471	      userId: user.id,
472	      action: "emailhosting.order",
473	      detail: `${name} plan=${plan.name}${external ? " (external — DNS verification required)" : ""}`,
474	    },
475	  });
476	
477	  // Fix A — the itemised invoice DOCUMENT + its emailed PDF for a business-email
478	  // order. Fires here in the CORE placement fn, so it runs exactly once for BOTH the
479	  // wallet path (orderEmailHosting) and the card path (placeEmailCardOrder →
480	  // fulfilCheckoutSession → here). Post-commit and fully best-effort: the wallet has
481	  // already been debited, so a mail/invoice failure must NEVER surface as an order
482	  // failure. Business Email is untaxed and never first-month-free, so the amount is
483	  // the real debited cents (the full term charge).
484	  try {
485	    const invTermLabel = vpsTerm(term).label;
486	    const invDesc = `Business Email: ${plan.name} for ${name} — ${invTermLabel}`;
487	    const createdInvoice = await db.invoice.create({
488	      data: invoiceCreateData({
489	        userId: user.id,
490	        description: invDesc,
491	        status: "PAID",
492	        taxCents: 0,
493	        taxRatePercent: 0,
494	        taxCountry: null,
495	        period: { start: new Date(), end: addMonths(new Date(), term) },
496	        lineItems: [{ description: invDesc, qty: 1, unitCents: debitedCents, amountCents: debitedCents }],
497	      }),
498	    });
499	    const { sendMail, emails } = await import("./mailer");
500	    const branding = await invoiceBranding();
501	    const tpl = emails.invoiceNew(
502	      {
503	        invoiceNumber: formatInvoiceNumber(createdInvoice.number, branding.numberPrefix),
504	        amount: `$${(createdInvoice.amountCents / 100).toFixed(2)}`,
505	        dueDate: new Date().toLocaleDateString("en-US", { year: "numeric", month: "short", day: "numeric" }),
506	        description: invDesc,
507	      },
508	      true, // the itemised PDF is attached (invoiceId passed below)
509	    );
510	    await sendMail({
511	      to: user.email,
512	      subject: tpl.subject,
513	      html: tpl.html,
514	      template: tpl.template,
515	      invoiceId: createdInvoice.id,
516	      userId: user.id,
517	      kind: "invoice",
518	    });
519	  } catch {
520	    /* invoice + email is best-effort — a placed order must never fail on it */
521	  }
522	
523	  // Deploy-funnel COMPLETION — email's authoritative, server-side bottom of the
524	  // funnel, the counterpart to placeOrder / placeGameOrder / placeHostingOrder.
525	  // This core runs from BOTH the wallet-immediate path (orderEmailHosting) and
526	  // the card-funded fulfilment path (placeEmailCardOrder → fulfilCheckoutSession),
527	  // so recording it here — not in either caller — covers both without double
528	  // counting a retry. Best-effort + never disturbs a completed order.
529	  try {
530	    // stepIndex 4 = one past the client wizard's ORDER_STEPS (Domain=0, Plan=1,
531	    // Review=2) and its "Payment" tail marker at index 3 (components/customer/
532	    // EmailHosting.tsx) — mirrors how hosting/game/vps place Complete one past
533	    // their own last tracked step.
534	    await recordDeployFunnelComplete({ product: "email", step: "Complete", stepIndex: 4, userId: user.id });
535	  } catch {
536	    /* never let funnel bookkeeping affect a completed order */
537	  }
538	
539	  revalidatePath("/dashboard/email");
540	  return { ok: true };
541	}
542	
543	/**
544	 * Fulfil a CARD-funded business-email order from its PAID Stripe session. Safe to
545	 * expose as a server action: it trusts NOTHING from its caller but a Stripe session
546	 * id, which it re-retrieves and re-classifies server-side — a forged or foreign id
547	 * classifies as anything-but-emailOrder and returns a no-op. Called ONLY by
548	 * lib/fulfil-checkout.ts (the shared webhook+redirect bus) AFTER it has credited the
549	 * card leg to the wallet; this then runs the SAME `orderEmailHostingCore` the wallet
550	 * path uses (whose domain dupe guard is the placement idempotency), so the wallet is
551	 * debited once and a webhook + redirect can never create two subscriptions.
552	 */
553	export async function placeEmailCardOrder(sessionId: string): Promise<Result | { skip: true }> {
554	  const purpose = await getCheckoutPurpose(sessionId);
555	  if (purpose.kind !== "emailOrder") return { skip: true };
556	  const user = await db.user.findUnique({ where: { id: purpose.userId } });
557	  if (!user) return { error: "user not found for paid email order" };
558	  const { domainName, emailPlanId, termMonths } = purpose.intent;
559	  return orderEmailHostingCore(user, domainName, emailPlanId, termMonths);
560	}
