562	// ---------- External-domain DNS setup + verification ----------
563	
564	/**
565	 * Return the DNS records a customer must publish at their registrar for an
566	 * EXTERNAL domain so mail flows through the Nxeon mail server, plus the
567	 * ownership-verification record. Ownership-checked (caller must own the sub).
568	 *
569	 * The DKIM record is fetched from Mailcow (`mcGetDkim`) and cached in
570	 * `dkimRecord`; when Mailcow isn't configured (or has no key yet) a placeholder
571	 * note is returned so the panel still renders.
572	 */
573	export async function getEmailDnsRecords(
574	  subscriptionId: string,
575	): Promise<{
576	  error?: string;
577	  records?: DnsRecord[];
578	  verified?: boolean;
579	  external?: boolean;
580	  cloudflareConnected?: boolean;
581	}> {
582	  const user = await requireUser();
583	
584	  const sub = await db.emailSubscription.findUnique({ where: { id: subscriptionId } });
585	  if (!sub) return { error: "Subscription not found." };
586	  if (sub.userId !== user.id) return { error: "Not your subscription." };
587	
588	  const domain = sub.domainName;
589	
590	  // Resolve the DKIM TXT: prefer the cached value, else fetch + cache from Mailcow.
591	  let dkimTxt = sub.dkimRecord ?? null;
592	  if (!dkimTxt && mailcowConfigured()) {
593	    try {
594	      // Ensure the mail domain exists so Mailcow has generated a DKIM key.
595	      if (!(await mcDomainExists(domain))) {
596	        await mcCreateDomain(domain).catch(() => {});
597	      }
598	      dkimTxt = await mcGetDkim(domain);
599	      if (dkimTxt) {
600	        await db.emailSubscription
601	          .update({ where: { id: sub.id }, data: { dkimRecord: dkimTxt } })
602	          .catch(() => {});
603	      }
604	    } catch (e) {
605	      console.warn(`[mailcow] get dkim ${domain} failed:`, e);
606	    }
607	  }
608	
609	  const records: DnsRecord[] = [
610	    {
611	      type: "TXT",
612	      label: "Ownership verification",
613	      host: `_nxeon-verify.${domain}`,
614	      value: `nxeon-verify=${sub.verifyToken ?? ""}`,
615	      note: "Proves you control this domain. Required before mail is enabled.",
616	    },
617	    {
618	      type: "MX",
619	      label: "Mail routing (MX)",
620	      host: domain,
621	      value: MAIL_HOST,
622	      priority: MAIL_MX_PRIORITY,
623	    },
624	    {
625	      type: "TXT",
626	      label: "SPF",
627	      host: domain,
628	      value: SPF_VALUE,
629	      note: "Authorizes the Nxeon mail server to send for your domain.",
630	    },
631	    {
