658	/**
659	 * Verify that an EXTERNAL domain's owner has published our verification record.
660	 * Resolves the `_nxeon-verify` TXT via DNS and confirms it contains
661	 * `nxeon-verify=<verifyToken>`; the MX pointing at the mail host is accepted as
662	 * corroboration. The result is derived entirely server-side from live DNS —
663	 * client input never decides the outcome. Rate-limited per user + subscription.
664	 */
665	export async function verifyEmailDomain(subscriptionId: string): Promise<Result> {
666	  const user = await requireUser();
667	
668	  const sub = await db.emailSubscription.findUnique({ where: { id: subscriptionId } });
669	  if (!sub) return { error: "Subscription not found." };
670	  if (sub.userId !== user.id) return { error: "Not your subscription." };
671	  if (!sub.external) return { error: "This domain is managed by Nxeon — no verification needed." };
672	  if (sub.verified) return { ok: true };
673	  if (!sub.verifyToken) return { error: "No verification token on this subscription." };
674	
675	  const rl = checkRateLimit(`email-verify:${user.id}:${sub.id}`, {
676	    max: 6,
677	    windowMs: 60_000,
678	  });
679	  if (!rl.ok) {
680	    return { error: `Too many verification attempts. Try again in ${rl.retryAfterSec}s.` };
681	  }
682	
683	  const domain = sub.domainName;
684	  const expected = `nxeon-verify=${sub.verifyToken}`;
685	
686	  // Primary signal: the verification TXT record must contain our exact token.
687	  let tokenFound = false;
688	  try {
689	    const txt = await resolveTxt(`_nxeon-verify.${domain}`);
690	    // Each record may be split into multiple strings — join per-record chunks.
691	    tokenFound = txt.some((chunks) => chunks.join("").trim() === expected);
692	  } catch {
693	    tokenFound = false;
694	  }
695	
696	  // Corroboration: MX pointing at the mail host (does not substitute for the token).
697	  let mxOk = false;
698	  try {
699	    const mx = await resolveMx(domain);
700	    mxOk = mx.some((r) => r.exchange.replace(/\.$/, "").toLowerCase() === MAIL_HOST);
701	  } catch {
702	    mxOk = false;
703	  }
704	
705	  if (!tokenFound) {
706	    return {
707	      error: mxOk
708	        ? "MX is set, but the _nxeon-verify TXT record isn't visible yet. DNS can take a few minutes to propagate."
709	        : "Verification record not found yet. Add the _nxeon-verify TXT record and try again (DNS can take a few minutes).",
710	    };
711	  }
712	
713	  await db.emailSubscription.update({
714	    where: { id: sub.id },
715	    data: { verified: true, verifiedAt: new Date() },
716	  });
717	
718	  await db.auditLog.create({
719	    data: {
720	      userId: user.id,
721	      action: "emailhosting.verify",
722	      detail: `${domain}${mxOk ? " (MX + TXT)" : " (TXT)"}`,
723	    },
724	  });
725	  revalidatePath("/dashboard/email");
726	  return { ok: true };
727	}
