731	/**
732	 * Run the SPF / DKIM / DMARC / MX self-check for a subscription the caller owns.
733	 *
734	 * WHY: "my mail goes to spam" was previously undiagnosable from inside the
735	 * product — the platform owner hit exactly this and had to reach for an external
736	 * tool. This returns pass/fail per record with the value actually observed beside
737	 * the expected one, so the customer can see which DNS row is wrong.
738	 *
739	 * Two correctness rules this depends on:
740	 *   - DNS is read from the ZONE'S AUTHORITATIVE NAMESERVERS, never the system
741	 *     resolver (see lib/mail/deliverability.ts — this host's `hosts: files …`
742	 *     nsswitch order can answer from /etc/hosts and looks like a real lookup).
743	 *   - DKIM is compared against Mailcow's LIVE key, not `sub.dkimRecord`, which is
744	 *     a write-once cache that can outlive a key rotation.
745	 *
746	 * Rate-limited: each run makes several outbound DNS queries plus one Mailcow call.
747	 */
748	export async function checkEmailDeliverability(
749	  subscriptionId: string,
750	): Promise<{ error?: string; report?: DeliverabilityReport }> {
751	  const user = await requireUser();
752	
753	  const sub = await db.emailSubscription.findUnique({ where: { id: subscriptionId } });
754	  if (!sub) return { error: "Subscription not found." };
755	  if (sub.userId !== user.id) return { error: "Not your subscription." };
756	  // A cancelled subscription's domain may since have been taken by another
757	  // customer (the duplicate guard in orderEmailHosting only excludes CANCELLED
758	  // rows), so the old owner must not keep a live probe pointed at it.
759	  if (sub.status === "CANCELLED") return { error: "This subscription is cancelled." };
760	
761	  // NOTE on domain verification: this check deliberately does NOT require
762	  // `sub.verified`, unlike every action that changes mail routing. It only READS
763	  // public DNS and Mailcow's public DKIM key, changes nothing, and an unverified
764	  // domain is precisely the case a customer needs it for — gating it would hide
765	  // the diagnosis exactly when the records are wrong. Ownership of the
766	  // subscription is still required so the panel can't be used to scan arbitrary
767	  // domains through our server.
768	  const rl = checkRateLimit(`email-deliverability:${user.id}`, { max: 10, windowMs: 60_000 });
769	  if (!rl.ok) return { error: `Too many checks. Try again in ${rl.retryAfterSec}s.` };
770	
771	  // LIVE key only. A failure here degrades the DKIM row to "unknown" rather than
772	  // silently comparing against a cached value that may no longer sign anything.
773	  let dkim: { selector: string; txt: string } | null = null;
774	  if (mailcowConfigured()) {
775	    try {
776	      const live = await mcGetDkimDetails(sub.domainName);
777	      if (live) dkim = { selector: live.selector, txt: live.txt };
778	    } catch (e) {
779	      console.warn(`[mailcow] live dkim lookup for ${sub.domainName} failed:`, e);
780	    }
781	  }
782	
783	  try {
784	    const report = await checkDeliverability({
785	      domain: sub.domainName,
786	      mailHost: MAIL_HOST,
787	      spfInclude: SPF_INCLUDE,
788	      spfExpected: SPF_VALUE,
789	      dmarcExpected: DMARC_VALUE,
790	      dkim,
791	    });
792	    return { report };
793	  } catch (e) {
794	    console.warn(`[deliverability] check for ${sub.domainName} failed:`, e);
795	    return { error: "Couldn't complete the DNS check right now. Please try again in a moment." };
796	  }
797	}
